// The faces the page starter draws with, embedded so they draw on any machine: Inter 700 and 600 and JetBrains Mono 400
// (SIL Open Font License 1.1, library/media/fonts, as packaged by Fontsource). A face named by the system's name falls
// back without a word (TRAPS.md: fonts): Bahnschrift, Segoe UI and Consolas are Windows faces, and a Mac has none of them.
// One copy: the page kit gets it as kit/lib/faces.ts. tests/test_docs.py checks these are the files in
// library/media/fonts, byte for byte.
export const INTER_700 = "data:font/woff2;base64,";
export const INTER_600 = "data:font/woff2;base64,";
export const JETBRAINS_MONO = "data:font/woff2;base64,";
/** the @font-face rules for the three faces: put <style>{FACES}</style> in the film once */
export const FACES = `@font-face { font-family: "Inter"; src: url(${INTER_600}) format("woff2"); font-weight: 100 650; } ` +
  `@font-face { font-family: "Inter"; src: url(${INTER_700}) format("woff2"); font-weight: 651 1000; } ` +
  `@font-face { font-family: "JetBrains Mono"; src: url(${JETBRAINS_MONO}) format("woff2"); font-weight: 100 1000; } `;
